import{_ as t}from"./chunks/info-pending-downloads.DZEQoJ1v.js";import{c as o,Q as n,j as a,m as s}from"./chunks/framework.BqPkuuVc.js";const r="/assets/info-home.Cind7i5T.png",i="/assets/info-clock-settings.CRxDFXsz.png",h="/assets/info-clock-event-time.BdaBxpeU.png",c="/assets/info-clock-pre-start.C4cLhXMe.png",l="/assets/info-starters.0uFt5K2d.png",d="/assets/info-radio-feed-picker.DIVUE0PV.png",g="/assets/info-radio-feed.DaZI6_og.png",p="/assets/info-radio-feed-tv.B09bhB9K.png",u="/assets/info-video-capture-setup.DN-tEKyj.png",w="/assets/info-video-picker.CpMVJfPr.png",S=JSON.parse('{"title":"Event info screens","description":"","frontmatter":{},"headers":[],"relativePath":"user/screens/info-screens.md","filePath":"user/screens/info-screens.md"}'),m={name:"user/screens/info-screens.md"};function f(b,e,y,k,v,T){return n(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="event-info-screens" tabindex="-1">Event info screens <a class="header-anchor" href="#event-info-screens" aria-label="Permalink to &quot;Event info screens&quot;">​</a></h1><p><strong>Audience:</strong> Organisers and timing operators putting view-only screens up around the arena, and the start-lane or download-tent volunteers who read them.</p><p>The <strong>info screens</strong> are full-screen displays you prop up where people need to see something: a clock at the start lanes, upcoming starters box by box, who has just come past a radio control, who still has to download their card, and a camera pointed at somewhere worth watching. You open one on a tablet, a laptop driving a TV, or a phone, choose what it shows, and walk away.</p><p>They are deliberately narrow:</p><ul><li><strong>Nothing on them changes the event.</strong> They only read. There is no editing, no card download, no way to alter a result from one. (The <strong>Camera</strong> screen is the one that sends something <em>to</em> Manager — its own pictures — and it is the only one that will ask for your access PIN.)</li><li><strong>Nobody has to stand at them.</strong> The device stays awake on its own and the screen keeps working unattended for the rest of the day.</li><li><strong>They follow whichever event is live.</strong> There is no event picker, so the same link works at your next event. A screen switched on before the event starts waits and picks the event up on its own.</li></ul><p><img src="'+r+'" alt="The Event info screens menu: six large tiles — Start clock, Starters, Radio control, Pending downloads, Video and Camera, each with a one-line subtitle — and the event clock in the top-right corner."></p><table tabindex="0"><thead><tr><th>Screen</th><th>What it answers</th></tr></thead><tbody><tr><td><strong>Start clock</strong></td><td>The time — or the start time of the box standing in front of it</td></tr><tr><td><strong>Starters</strong></td><td>Upcoming starters, one column per pre-start box</td></tr><tr><td><strong>Radio control</strong></td><td>Who has just come past a chosen radio control</td></tr><tr><td><strong>Pending downloads</strong></td><td>Who finished but has not had their card read</td></tr><tr><td><strong>Video</strong></td><td>A camera at the arena — live now, or something recorded earlier</td></tr><tr><td><strong>Camera</strong></td><td>Sends <em>this</em> device&#39;s camera to Manager</td></tr></tbody></table><h2 id="opening-a-screen" tabindex="-1">Opening a screen <a class="header-anchor" href="#opening-a-screen" aria-label="Permalink to &quot;Opening a screen&quot;">​</a></h2><p>Each device opens the same address — the server address followed by <code>/info</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;server-address&gt;/info</span></span></code></pre></div><p>The easiest way to get it is <strong>Settings → Server → Access links</strong>, where it is listed as <strong>Event info screens</strong>. Copy that link to the device. Which of the two links to use — the name one or the IP one — depends on the device; see <a href="./../reference/server-addresses">Reaching the server: name or IP</a>. Phones, tablets and TVs normally work with the name link.</p><p>Then, on the device:</p><ol><li>Open the link. The menu above appears.</li><li><strong>Tap the tile</strong> for what this screen is going to show. That opens the screen&#39;s <strong>settings</strong> — what the clock shows, which controls a feed watches, how large the names are drawn.</li><li>Set it up — a preview at the top shows what you are building — then press <strong>Show</strong> at the bottom. That press also takes the browser&#39;s address bar off, so the screen fills the display.</li><li>Prop the device up and leave it.</li></ol><blockquote><p><strong>Tip:</strong> The link carries no event id, so it does not go stale. A tablet set up at the start lane this weekend will pick up your next event without anyone touching it.</p></blockquote><blockquote><p><strong>Note:</strong> Taking the address bar off only works when you press the button — a browser will not let a page go full-screen on its own, so it can never happen on a reload. If a screen restarts and comes back with browser chrome around it, go back to its settings (below) and press the button again. Some devices refuse full-screen altogether (an iPhone has no way to do it at all); the screen still works, it just keeps its address bar.</p></blockquote><h2 id="changing-settings-and-getting-back-out" tabindex="-1">Changing settings, and getting back out <a class="header-anchor" href="#changing-settings-and-getting-back-out" aria-label="Permalink to &quot;Changing settings, and getting back out&quot;">​</a></h2><p>Every screen is reached through its own settings page, and that page is where you go back to.</p><p><img src="'+i+'" alt="The Start clock settings page: a Preview panel above showing a dark clock reading 09:16:39, then &quot;This clock shows&quot; with Event time selected among the pre-start options, &quot;Appearance — Dark&quot;, a Beep row reading On and &quot;Beep interval — Every 2 minutes&quot;, with Back and Show buttons across the foot."></p><p>Everything on it is a big button — no dropdowns and no switches, because these are set up with a fingertip on a tablet standing on a table, often by someone who has not seen the app before. Whatever you tap takes effect straight away; there is nothing to save.</p><p><strong>The panel at the top is the screen itself, drawn small.</strong> It is the real thing rather than a picture of one, so it follows every choice as you make it: switch a clock to Dark, set it to a −3 box, make a list Huge, tick a second radio control, and the preview shows exactly what the device will be showing when you walk away from it.</p><p>Two buttons sit across the foot:</p><ul><li><strong>Back</strong> leaves this screen alone and goes back to the six tiles, so you can pick a different one.</li><li><strong>Show</strong> puts the display up and takes the browser&#39;s chrome off. On the camera screen it reads <strong>Start</strong>, because that is what the press does there.</li></ul><p>Once a screen is up, there is a small cog in the bottom-right corner. <strong>Press and hold it for two seconds</strong> — a ring fills round it — and you are back on the settings page. A hint saying so appears for the first few seconds, then fades.</p><p>That hold is the only way off a screen that is up: a stray tap, a swipe, or the browser&#39;s <strong>Back</strong> button will not do it. That is on purpose — these screens stand where the public can reach them. The settings page itself needs no such protection, which is why leaving <em>it</em> is one press.</p><blockquote><p><strong>Warning:</strong> The hold stops an accident, not a person. Anyone who works out the gesture can leave the screen. If you need a display that genuinely cannot be got out of, lock the device itself — Android&#39;s screen pinning, or Guided Access on an iPad.</p></blockquote><h3 id="settings-are-remembered-per-device" tabindex="-1">Settings are remembered per device <a class="header-anchor" href="#settings-are-remembered-per-device" aria-label="Permalink to &quot;Settings are remembered per device&quot;">​</a></h3><p>Each screen&#39;s settings are stored in that device&#39;s browser, not in the event. A tablet that reloads — or whose battery dies and is plugged back in — comes back showing the same thing it was showing before, without anyone walking over with a laptop. It also means two tablets can show different things, and that setting one up does not change the other.</p><blockquote><p><strong>Warning:</strong> If the settings page shows <strong>This device cannot save settings</strong>, that browser is refusing to store them (a private-browsing window, or a locked-down kiosk profile). Your choices hold until the page reloads and are then lost — and the defaults are not neutral: a silent pre-start clock comes back as an event-time clock <strong>with the beeps on</strong>, which sounds a start signal several minutes early. Use a normal browser window on that device, or check the screen after every restart.</p></blockquote><h2 id="start-clock" tabindex="-1">Start clock <a class="header-anchor" href="#start-clock" aria-label="Permalink to &quot;Start clock&quot;">​</a></h2><p>A full-screen clock, sized to be read across a start field. The digits change exactly on the second, because someone is going to step over the line as they do.</p><p><img src="'+h+'" alt="A full-screen dark start clock reading 10:30:13 in large white digits on black, filling the display."></p><p><strong>This clock shows</strong> picks between two things:</p><ul><li><strong>Event time</strong> — the actual time. This is the clock at the line.</li><li><strong>Pre-start −1</strong> … <strong>−5</strong> — the clock for a call-up box. It shows the time the runners standing in front of it will start, with a large <strong>−3</strong> badge naming the box and the real event time kept small in the top-left. A start official reading a −3 clock still needs to know what time it actually is, and a runner who reads a −2 clock as a −4 one walks into the wrong box — hence the size of the badge.</li></ul><p><img src="'+c+'" alt="A light pre-start clock reading 10:34 in black on white, &quot;EVENT TIME 10:30:13&quot; small in the top-left corner and a large &quot;−3&quot; badge in the top-right."></p><blockquote><p><strong>Note:</strong> A pre-start clock shows <strong>hours and minutes only</strong>, and rounds up to the start the box is waiting for. It is not telling you the time — it is showing the number printed on the start list of the runners in front of it, and that is always a whole minute. It changes on the move-up, so everyone standing in the box through that minute reads the same start time.</p></blockquote><p><strong>Appearance</strong> is <strong>Dark</strong> or <strong>Light</strong> — pick it for where the screen physically stands (bright sun, a dim tent), not for what the device&#39;s own theme is set to.</p><h3 id="beeps" tabindex="-1">Beeps <a class="header-anchor" href="#beeps" aria-label="Permalink to &quot;Beeps&quot;">​</a></h3><table tabindex="0"><thead><tr><th>This clock shows</th><th>Beep pattern</th><th>Default</th></tr></thead><tbody><tr><td><strong>Event time</strong></td><td>A short beep on each of the seconds before the interval, and the long beep exactly <strong>on</strong> it. The long beep is the start signal.</td><td>On</td></tr><tr><td><strong>Pre-start −N</strong></td><td>Two very short blips on the interval, to move the boxes up.</td><td>Off</td></tr></tbody></table><p>The pattern follows the mode — it is not a separate setting. A pre-start clock deliberately does not count down, because nobody starts at it and a lead-in there is a false start signal every couple of minutes all morning. The double blip matters for the same reason: a <em>single</em> beep beside a start lane is the sound everyone within earshot is listening for, so a box that is only shuffling forward must not make one.</p><p><strong>Beep interval</strong> offers every 30 seconds, every minute, every 2 minutes, or every 3 minutes. Two minutes is the default.</p><p><strong>Short beeps</strong> is how long the countdown is on the clock at the line: <strong>2</strong>, <strong>3</strong> or <strong>4</strong> short beeps, one per second, ending on the long one. Four is the default — a runner who hears the first of four has a whole second to look up before the three that mean <em>now</em> — and two is there for a lane running 30-second intervals, or one standing within earshot of another, where four is simply noise.</p><p><strong>Warning beep 10 seconds before</strong> adds one beep ten seconds ahead of each start, for a lane with a long call-up. It is off unless you ask for it, and it is deliberately a <strong>lower, slower</strong> sound than the countdown beeps: nobody should be able to hear it as the countdown having started and step off early.</p><blockquote><p><strong>Note:</strong> Both of those settings are only offered when the clock is showing <strong>Event time</strong>. A pre-start clock is not counting down to anything, so there is no lead-in to lengthen and no start to warn of. Your choices are remembered while it is set that way, and come back if you set it to event time again.</p></blockquote><blockquote><p><strong>Warning:</strong> Check the beeps before the first start. A browser will not make a sound until the page has been touched, so a clock that has just reloaded shows <strong>Tap the screen once to let this device play the beep</strong> across the bottom — and until somebody does, it keeps perfect time in silence. If it instead says the device cannot play the beep at all, that device has no usable sound output; the clock still runs.</p></blockquote><h2 id="starters" tabindex="-1">Starters <a class="header-anchor" href="#starters" aria-label="Permalink to &quot;Starters&quot;">​</a></h2><p>Upcoming starters, one column per pre-start box. Two people read it: a competitor checking whether they are up next, and the start team checking the right people are standing in the right box.</p><p><img src="'+l+'" alt="The Starters screen with four columns headed 10:31 (−1), 10:32 (−2), 10:33 (−3) and 10:34 (−4). Each column holds cards with a competitor&#39;s name and their class and course beneath — Hana Nováková, M20, Course 3 in the −1 box, and so on."></p><p><strong>A column is a clock time, not a place in the start list.</strong> The <strong>−4</strong> column is whoever starts four boxes from now, whether that is six people or nobody. An empty box is worth showing: it tells a start official the lane is about to have a gap, and it says so under the heading <strong>Nobody</strong>.</p><p><strong>The columns count down to the line</strong> — the box furthest from starting on the left, the runners about to go on the right — so the screen reads the way the lane is walked.</p><p>Set <strong>Start interval</strong> to the interval your start list was drawn on: <strong>30 seconds</strong>, <strong>1 minute</strong>, <strong>2 minutes</strong> or <strong>3 minutes</strong>. It is what the columns are counted in, which is why the settings page asks for it first. On a 30-second start the headings carry seconds as well, since two boxes half a minute apart cannot be told apart by the minute alone.</p><p>In <strong>Columns</strong> you then tick which boxes this screen draws:</p><ul><li><strong>Next</strong> is the next start time anyone is actually in, however far ahead that is. Where the lane is running to time it is the same as the first box; where the start list has a gap in it, it is the more useful answer.</li><li>The other seven are the boxes behind it, and <strong>each is labelled with how far ahead of the line it is</strong> rather than with a number to multiply — so a 30-second start offers −30 sec, −1 min, −1m30s, −2 min, −2m30s, −3 min, −3m30s, and a three-minute start offers −3 min through to −21 min. Change the interval and the labels follow it.</li></ul><p>Each card shows the competitor&#39;s name with their class and course beneath. Anyone marked as not starting — did-not-start, not participating, cancelled — is left out, as is anyone who has no start time yet. A box holding more names than fit <strong>scrolls</strong> on its own, without moving the columns beside it.</p><p><strong>Size</strong> (Small, Medium, Large, Huge) sets how big the cards are drawn. Pick it for the reading distance: Huge for a screen people walk past, Small when you want as much of the lane on screen as possible.</p><h2 id="radio-control" tabindex="-1">Radio control <a class="header-anchor" href="#radio-control" aria-label="Permalink to &quot;Radio control&quot;">​</a></h2><p>Who has just come past a radio control, newest first. This is the screen for a spectator control or a changeover — the one people stand and watch.</p><p>Every time it opens, its settings ask which controls to watch:</p><p><img src="'+d+'" alt="The Radio control settings page: &quot;Choose the controls this screen watches&quot; above two tiles — Ridge (Punches: 0) and Spectator (Punches: 3) — with Back and Watch buttons across the foot."></p><p>The list holds every control you have flagged as a radio, plus any control code that is actually reporting punches even if nobody flagged it. The <strong>Punches</strong> count is how you tell a control is alive before you commit a screen to it. Tap as many tiles as you want — they stay lit — then <strong>Watch</strong>.</p><p>The screen asks every time because a tablet is usually carried to a different control at the next event, and a feed that quietly came back on yesterday&#39;s control would show the crowd the wrong names. Whatever the device was watching last is already ticked, so carrying on where you left off is one press. Until at least one is ticked the button will not do anything — a feed watching nothing has nothing to show.</p><p><img src="'+g+'" alt="The Spectator feed on a tablet: three cards, each with a large place number captioned PLACE, the competitor&#39;s name with class and course beneath, the time AT THE RADIO, and on the right either PREDICTED FINISH or TIME with a green OK chip. Jonas Lindqvist is predicted 47:12; Sofia Duarte shows 44:07 in italics with a trailing asterisk; Mikko Virtanen shows 41:22."></p><p>Each card reads left to right:</p><ul><li><strong>PLACE</strong> — where they are in the race right now. In a relay this is the <strong>team&#39;s</strong> place, because that is the standing anyone at the fence is following, not the leg runner&#39;s rank among every runner in the class.</li><li><strong>Name</strong>, with class and course beneath.</li><li><strong>AT THE RADIO</strong> — the time of day they came past.</li><li><strong>PREDICTED FINISH</strong> — the time they are on course for, while they are still out.</li><li><strong>TIME</strong> and a status chip — once they finish, the row swaps the prediction for the time and status they ended up with. Somebody who came past twenty minutes ago has usually finished by the time anyone reads the bottom of the screen.</li></ul><blockquote><p><strong>Note:</strong> A time in <em>italics with a trailing asterisk</em> came from the radio finish and has not been confirmed by a card download yet. It is a real time, but it can still change. See <a href="./../running-the-event/card-download">Downloading cards</a>.</p></blockquote><p><strong>Columns</strong> lays the feed out 1 to 4 across. One column suits a tablet held upright beside the control; three or four put much more of the field on a big TV at once.</p><p><img src="'+p+'" alt="The same Spectator feed on a 1920×1080 TV with three columns across, each card laid out with its place badge, name, class and course, radio time and result."></p><h3 id="watching-more-than-one-control" tabindex="-1">Watching more than one control <a class="header-anchor" href="#watching-more-than-one-control" aria-label="Permalink to &quot;Watching more than one control&quot;">​</a></h3><p>An arena often has more than one radio worth showing — the spectator control and the run-in, or two changeovers — and rarely a second tablet for the second one. Tick more than one and the screen splits into <strong>a column per control, headed by that control&#39;s name</strong>, drawn large enough to read from where the crowd is standing. The heading is what tells anyone which control the names under it came past, so it is not something to squint at.</p><p>Each column holds its own feed, newest first, and scrolls on its own without moving the columns beside it. The count under a heading is that control&#39;s punch total — the same &quot;is it alive&quot; check the picker gives you, kept on screen all day.</p><p><strong>Columns</strong> greys out while more than one control is ticked: the controls <em>are</em> the columns then, and three across inside each of them is not a layout anyone wants. Untick back down to one control and the setting comes back. Untick them all and the screen returns to the picker.</p><h2 id="pending-downloads" tabindex="-1">Pending downloads <a class="header-anchor" href="#pending-downloads" aria-label="Permalink to &quot;Pending downloads&quot;">​</a></h2><p>Who the finish saw come home but whose card has never been read — the runners who walk off to their car with the card still in their hand.</p><p><img src="'+t+'" alt="The Pending downloads screen headed &quot;Pending downloads 4&quot;, with four large cards — Sofia Duarte, Elin Karlsson, Tom Bradbury and Aoife Ní Dhomhnaill — each carrying a red &quot;Download pending&quot; badge."></p><p>Put this one where finishers can see it: outside the download tent, or at the exit of the arena. Longest overdue is at the top, and the count beside the title is the number outstanding. When the last card is read the screen says <strong>Everyone has downloaded</strong>.</p><p><strong>Competitors still out on the course are deliberately not on this list.</strong> They are a different problem — somebody who may still be running, or may be hurt — and putting them here would bury the two or three names the download tent is chasing under the whole field for most of the morning. For who is still in the forest, use <a href="./../running-the-event/safety-check">Safety check: accounting for everyone</a>.</p><blockquote><p><strong>Note:</strong> This screen needs a <strong>radio finish control</strong>. Without one, nothing distinguishes a runner still in the forest from one who has gone home, so the screen has nothing to show. See <a href="./../running-the-event/radio-punches">Radio punches</a>.</p></blockquote><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2><p>Two screens that work as a pair: <strong>Camera</strong> turns a phone or tablet into a camera pointed at somewhere worth watching, and <strong>Video</strong> is what everyone else looks at.</p><h3 id="setting-a-camera-up" tabindex="-1">Setting a camera up <a class="header-anchor" href="#setting-a-camera-up" aria-label="Permalink to &quot;Setting a camera up&quot;">​</a></h3><p>Prop a device where it can see what you want seen — a spectator control, the run-in, a relay changeover, the finish banner — open <code>/info</code> on it and choose <strong>Camera</strong>.</p><p><img src="'+u+'" alt="The Camera screen&#39;s settings: a field reading &quot;What this camera is called&quot; holding &quot;Spectator control&quot;, the question &quot;Which control does this camera overlook?&quot; with two tiles — Ridge and Spectator, the second one selected — and Back / Start buttons across the foot."></p><p>Give the camera a name people will recognise on a picker — &quot;Spectator control&quot;, &quot;Finish banner&quot; — and tick the control it overlooks. That tick is what puts the punches on the picture: everyone watching sees who has just come past, drawn over the video. Then press <strong>Start</strong> and put the device down.</p><p>The rest of the settings are about what the camera makes:</p><ul><li><strong>Burn the time into the picture</strong> draws a clock in a corner of every frame. It is on by default and it is the one setting you cannot undo afterwards — the clock is composited into the pictures before they are encoded, so it is in the recording for good. That is the point: a file watched back on somebody else&#39;s machine months later has nothing else to say when it was taken. <strong>Where the clock goes</strong> is yours to pick, because the empty corner at one control is the finish banner at the next.</li><li><strong>Show punches over the picture</strong> draws the same cards a viewing screen draws, over this device&#39;s own preview, so you can confirm the camera is pointed at the control you think it is without walking to a screen. These are drawn on top of the video rather than into it, so they never reach the recording.</li><li><strong>Camera</strong> picks the front or back lens, and <strong>Picture size</strong> picks how large a picture to ask for. Both are requests to the device — a camera that cannot manage what you asked says so rather than starting.</li></ul><p>While it is running the screen shows its own picture and, along the bottom, whether it is reaching Manager, how many screens are watching, and whether it is being recorded. <strong>To stop it, or to change anything, press and hold the button in the corner</strong> — the same gesture as every other info screen — which brings the settings back. That is deliberate: a camera anybody walking past could switch off is a camera that will be switched off.</p><p>The camera keeps running while you are on that page, so moving the clock out of a finish banner or fixing which control it overlooks costs nothing: nobody watching loses the picture, and the recording has no gap in it. <strong>Stop the camera</strong> is on the settings page too, on its own and in red.</p><blockquote><p><strong>Note:</strong> A browser will not give a web page its camera over an insecure connection. If the screen says so, open Manager on that device over <strong>HTTPS</strong> and try again — the address and the certificate to install are in <strong>Settings → Server</strong>. See <a href="./../reference/https-and-certificates">HTTPS and certificates</a>.</p></blockquote><h3 id="when-the-wifi-drops" tabindex="-1">When the wifi drops <a class="header-anchor" href="#when-the-wifi-drops" aria-label="Permalink to &quot;When the wifi drops&quot;">​</a></h3><p>It will. Venue wifi is not venue wifi for long, and the camera is built to expect it.</p><p><strong>The camera does not stop filming.</strong> It holds on to the pictures it cannot send, and when the link comes back it sends those first — so <strong>the recording is one continuous file</strong>, not one file per stumble with the gaps missing. A chip appears along the bottom saying how much it is holding, and the status chip beside it reads <strong>Reconnecting…</strong>; both go once it has caught up. The picture at the fence runs behind by however much there is to catch up on, and then comes back to live on its own.</p><p>There is a limit, and the screen says when it is reached: a phone can only hold so much before the browser would rather close the tab than let it. Past it, the oldest of what was held is dropped and <strong>a new recording begins</strong> when the link returns. How long is ridden out is <strong>Settings → Video → Ride out a dropped connection for</strong>, which is two minutes by default and shows you what that costs the device in megabytes at your chosen picture quality.</p><p>Two practical things either way. <strong>Plug the camera in</strong>: capturing and sending video all morning flattens a battery faster than anything else these screens do, and holding video while the wifi is out does not make it lighter work. And <strong>put the camera where the signal is</strong>, not where the view is best and the signal is worst — everything above is a way of surviving a bad link, not a substitute for a good one.</p><h3 id="watching" tabindex="-1">Watching <a class="header-anchor" href="#watching" aria-label="Permalink to &quot;Watching&quot;">​</a></h3><p>Choose <strong>Video</strong> and pick what to show. Live cameras come first, then anything recorded earlier at this event.</p><p><img src="'+w+'" alt="The Video screen&#39;s settings page, showing two tiles: a live one headed LIVE for &quot;Spectator control&quot;, and one headed RECORDED for &quot;Finish banner&quot; with its time, length and size."></p><p>A live camera fills the screen with the punches at its control drawn down one side, so the crowd at a fence gets the picture and the names together. A recording gets the ordinary video controls, so you can scrub, pause and step through it.</p><p><strong>On a recording the punches follow the picture.</strong> Wind back to 10:42 and the cards show what was known at 10:42 — which is what makes this worth having for a commentator catching up on a leg they missed, or for an official settling who crossed the line first.</p><p>The screen asks which camera it is showing every time it is opened. A tablet gets carried to a different corner of the arena far more often than it is left in one, and a screen that quietly resumed on yesterday&#39;s camera would show a crowd the wrong thing. Pick a tile, then press <strong>Watch</strong>.</p><p><strong>A viewing screen looks after itself.</strong> If it loses the server, or the camera loses the server, it says which of the two has happened and keeps trying — you do not have to walk over and pick the camera again. When the picture comes back it <strong>jumps to what is happening now</strong> rather than playing out the minutes it missed, which is what a crowd at a fence wants. A camera that has genuinely been switched off says so, and is picked up again by itself if somebody switches it back on.</p><h3 id="what-is-recorded-and-what-is-not" tabindex="-1">What is recorded, and what is not <a class="header-anchor" href="#what-is-recorded-and-what-is-not" aria-label="Permalink to &quot;What is recorded, and what is not&quot;">​</a></h3><p>Cameras record by default, so the footage exists if it turns out to be needed — nobody knows at nine in the morning that the finish will need looking at twice. Whoever sets a camera up can turn recording off for that one, and <strong>Settings → Video</strong> holds the installation-wide defaults: whether to record at all, how long to keep recordings, the picture quality, the free-disk floor below which recording stops, and how long a dropped connection is ridden out.</p><p>Three things to know about what is kept:</p><ul><li><strong>Recordings are not in your event backups and are not sent to the cloud.</strong> They are far too large — a camera is roughly 675 MB an hour — and including them would turn a backup that takes seconds into one that takes minutes. <strong>Restoring an event on another machine will not bring its video with it.</strong> If you need the files, copy them off this server yourself; the <strong>Screens</strong> page’s Video section names the folder.</li><li><strong>They are tidied away some time after the event they belong to is deleted</strong>, and after the retention period you set. The tidy-up runs while Manager is open, so a Manager left closed all week does not do it until it is next opened.</li><li><strong>There is no sound.</strong> A camera at a spectator control would otherwise record every conversation within a few metres of it, all day.</li></ul><blockquote><p><strong>Note:</strong> Some devices cannot encode video in a browser at all. Those fall back to sending <strong>still pictures</strong> a few times a second — enough to see a runner go past, and the screen says so at both ends. Still pictures are live only and are never recorded.</p></blockquote><h2 id="when-the-network-drops" tabindex="-1">When the network drops <a class="header-anchor" href="#when-the-network-drops" aria-label="Permalink to &quot;When the network drops&quot;">​</a></h2><p>These screens are built to survive an outage that lasts the rest of the event, and they mostly do — but it is worth knowing what you are looking at.</p><ul><li><strong>Lists do not blank.</strong> Whatever a screen had read stays on it. The starters screen keeps filling and emptying its boxes correctly for as long as the tablet has power, because its columns are minutes counted off the clock against start times that were settled before the race began.</li><li><strong>The clock keeps time.</strong> It carries on from the last reading it got from the server.</li><li><strong>A warning appears beside the clock</strong> once the link has been down for a while, and clears the moment it comes back. The start clock deliberately never shows it: it is read by everyone walking up to the line, and a warning symbol there would tell a hundred competitors their start times are in doubt in order to tell one official something they can read off any other screen.</li><li><strong>A screen that could not read the event at all</strong> says <strong>Could not read the event. What is shown may be out of date.</strong> rather than showing an empty list — because &quot;everyone has downloaded&quot; and &quot;we never got the list&quot; look identical otherwise.</li></ul><blockquote><p><strong>Warning:</strong> Do not reload a screen during an outage. The page itself comes from the server, so a reload lands on an error page and the screen cannot come back until the network does. Leave it alone; it recovers on its own when the link returns.</p></blockquote><p>If a screen shows <strong>There is no live event at the moment</strong>, no event has been started yet. Leave it up — it starts on its own as soon as one is under way. And if it complains that the device&#39;s time zone does not match the event&#39;s, fix the time zone in the device&#39;s own settings: everything on these screens is a clock time, and it will be wrong until you do.</p><h2 id="practical-setup" tabindex="-1">Practical setup <a class="header-anchor" href="#practical-setup" aria-label="Permalink to &quot;Practical setup&quot;">​</a></h2><ul><li><strong>Plug the device in.</strong> The screens hold the display awake, which is what you want and also what flattens a battery by lunchtime.</li><li><strong>Check each screen once it is in place</strong>, from where people will actually read it. Size is the setting operators most often get wrong from a metre away.</li><li><strong>Anyone on your network with the link can open these screens.</strong> There is nothing secret on them — they show what the spectator screens show — but do not treat the link as private.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./creating-screens">Creating Leaderboard screens</a> — the results screens for the arena</li><li><a href="./commentary">Commentary</a> — the announcer&#39;s live feed</li><li><a href="./../running-the-event/radio-punches">Radio punches</a> — where the radio feed&#39;s punches, and the video overlay&#39;s, come from</li><li><a href="./../reference/https-and-certificates">HTTPS and certificates</a> — what a camera device needs before a browser will hand over its camera</li><li><a href="./../running-the-event/safety-check">Safety check: accounting for everyone</a> — who is still out on the course</li><li><a href="./../reference/server-addresses">Reaching the server: name or IP</a> — which link to give each device</li><li><a href="./../event-setup/start-times">Start times</a> — what the starters screen is reading</li></ul>',113)])])}const P=o(m,[["render",f]]);export{S as __pageData,P as default};
